"""Load mirt reference cases from tests/reference/*.json (generated by validation/r/*.R)."""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd

REFERENCE_DIR = Path(__file__).parent / "reference"


@dataclass(frozen=True)
class Case:
    name: str
    raw: dict[str, Any]

    @property
    def items(self) -> list[str]:
        return list(self.raw["items"])

    @property
    def itemtype(self) -> str:
        return str(self.raw["meta"]["itemtype"])

    @property
    def patterns(self) -> pd.DataFrame:
        return pd.DataFrame(np.asarray(self.raw["patterns"], dtype=int), columns=self.items)

    @property
    def data(self) -> pd.DataFrame:
        counts = np.asarray(self.raw["counts"], dtype=int)
        return pd.DataFrame(
            np.repeat(np.asarray(self.raw["patterns"], dtype=int), counts, axis=0),
            columns=self.items,
        )

    def params(self, key: str = "params") -> pd.DataFrame:
        src = self.raw[key] if key == "params" else self.raw[key]["params"]
        return pd.DataFrame(src).T.astype(float).loc[self.items]

    def latent(self, key: str = "latent") -> dict[str, float | None]:
        src = self.raw[key] if key == "latent" else self.raw[key]["latent"]
        return {k: (None if v is None else float(v)) for k, v in src.items()}


def load(name: str) -> Case:
    return Case(name, json.loads((REFERENCE_DIR / f"{name}.json").read_text()))
